list_dashboard_banners.code:
final response = await client.dashboardBanners.listDashboardBanners();
for (final banner in (response.map as Map)['banners'] as List) {
  print('${(banner as Map)['key']} ${banner['title']} ${banner['active']}');
}

create_dashboard_banner.code:
final response = await client.dashboardBanners.createDashboardBanner({
  'key': 'spring_sale',
  'title': 'Spring sale',
  'description': 'Ends Friday.',
  'tags': ['Sales'],
  'icon': 'tag',
  'learn_more': {
    'action': 'open_link',
    'label': 'Learn more',
    'url': 'https://example.com/spring-sale',
  },
});
final banner = response.map as Map;
print('${banner['key']} ${banner['position']}');

get_dashboard_banner.code:
final response =
    await client.dashboardBanners.getDashboardBanner('spring_sale');
final banner = response.map as Map;
print('${banner['title']} ${banner['active']}');

patch_dashboard_banner.code:
final response = await client.dashboardBanners.patchDashboardBanner(
  'spring_sale',
  {'title': 'Spring sale ends today', 'active': false},
);
final banner = response.map as Map;
print('${banner['title']} ${banner['active']}');

